import React from "react";
import { createRoot } from "react-dom/client";
import ChatBot from "react-chatbotify";

const App = ({ settings }) => {
  console.log("Settings received in App.js:---------------->", settings); 
  return (
    <div>
      <ChatBot settings={settings} />
    </div>
  );
};

const rootElement = document.getElementById("root");
const settingsFromParent = window.chatBotSettings; // get from parent app

const root = createRoot(rootElement);
root.render(<App settings={settingsFromParent} />);

export default App;
